from lib import *
S = SS('w11')
steps = [
    step("netstat -rn -f inet 的列:Destination(目的地)、Gateway(网关)、Flags、Netif(出口接口)、Expire(剩余寿命)。几条有代表性的:default → 网关是局域网里的路由器,标志 UGScg(U 可用、G 经网关、S 静态、c/g 与克隆和默认路由有关);127 → 127.0.0.1,出口 lo0,标志 UCS;169.254 → link#14,出口 en0,标志 UCS(链路本地网段,直连);局域网那条带 /22 → link#14,UCS,直连;224.0.0/4 → 组播,标志带 m;255.255.255.255/32 → 受限广播。Gateway 栏里 link#14 表示“直连,出口接口号 14,下一跳就是目的地本身”。flags 字母:U 可用、G 经网关、H 主机路由、S 静态、C 可克隆、L 带链路层地址、W 克隆产生、I 绑定接口、i 地址已解析、m 组播、b 广播。", t=tl(S(1)), mark=lidx(S(1), 'default', '224.0.0/4'), done=lidx(S(1), 'Destination', '127   ', '169.254', '255.255.255.255/32', '出现过的 flags'), kv=KV([['Gateway = link#N', '直连,下一跳是目的地本身'], ['Gateway = 地址', '经这个网关转发'], ['UGScg', '默认路由']], ['Gateway = link#N'])),
    step("route get 看内核对某个目的地实际选哪条路由:127.0.0.1 → 主机路由、出口 lo0(标志 HOST LOCAL);本机自己 en0 地址 → 标志含 LOCAL,出口 lo0(发给自己的包走回环,不出网卡);同网段邻居 → 局域网那条 /22(掩码 255.255.252.0),直连、出口 en0,标志 CLONING;公网 8.8.8.8 → default,网关是局域网路由器,出口 en0,标志 GATEWAY;组播 224.0.0.1 → 224.0.0.0/240.0.0.0,出口 en0,标志 MULTICAST;链路本地 169.254.1.1 → 169.254.0.0/255.255.0.0,出口 en0。CLONING 表示这条路由用到时会为具体目的地克隆出一条主机路由(ARP 邻居条目就是这么来的)。", t=tl(S(2)), mark=lidx(S(2), '回环', '本机自己'), done=lidx(S(2), '同网段的邻居', '公网地址', '组播', '链路本地'), kv=KV([['公网地址', 'default + 网关'], ['同网段', '直连,不经网关'], ['本机自己的地址', 'LOCAL,走 lo0']], ['公网地址'])),
    step("自己实现最长前缀匹配:把本机的 206 条路由读进来,对 12 个目的地“匹配所有路由、取前缀最长的”,再与内核 route get 选出的接口比较:11 个一致(127.0.0.1 → /32 → lo0;邻居 → /32 → en0;8.8.8.8、1.1.1.1、10.0.0.1、172.16.0.1、203.0.113.9 都没有更具体的路由,落到 default /0 → en0;224.0.0.251 → en0;169.254.100.1 → /16 → en0)。唯一不一致的是本机自己 en0 的地址:netstat 的表里它的出口写的是 en0,而 route get 报告它是一条 LOCAL 主机路由、出口 lo0——内核对本机地址有专门处理,发给自己的包走回环。多条路由同时匹配时,总是前缀最长的赢:路由表里的前缀长度有 /0、/4、/8、/16、/22、/32。", t=tl(S(3)), mark=lidx(S(3), '不一致', '12 个目的地里'), done=lidx(S(3), '127.0.0.1  ', '8.8.8.8  ', '路由表里一共有'), b=bars([['12 个目的地', 12, '12'], ['与内核一致', 11, '11'], ['不一致(本机地址)', 1, '1']], 12, mark=[2], done=[0, 1]), kv=KV([['规则', '最长前缀优先'], ['default', '没有更具体路由时的兜底'], ['本机地址', '内核特殊处理,走 lo0']], ['规则'])),
    step("查表的代价:同样是最长前缀匹配,表里放 20000 条随机路由、查 5000 个随机地址。逐条扫描每次要 1281 µs(共 6406 ms);按前缀长度分桶、每个桶用哈希,每次只要 0.9 µs(共 4 ms),两种方法结果完全一致;5 万次查询用 43 ms。分桶的做法最多比较 8 个前缀长度,与路由条数无关。真实的路由器用 trie 或硬件 TCAM,思路相同:不要逐条比较。", t=tl(S(4)), mark=lidx(S(4), '逐条扫描', '分桶哈希'), done=lidx(S(4), '逐条扫描'), b=bars([['逐条扫描 每次', 1281, '1281 µs'], ['分桶哈希 每次', 0.9, '0.9 µs']], 1281, mark=[1], done=[0]), kv=KV([['20000 条路由', '逐条扫描 1281 µs / 次'], ['分桶 + 哈希', '0.9 µs / 次'], ['两者', '结果一致']], ['分桶 + 哈希'])),
]
